import { failureLine, runEntire } from './entire-cli.mjs'
import { workspaceHost } from './hosts.mjs'
import { resolveFocusedWorkspace } from './workspace.mjs'

const VERSION = { key: 'version', label: 'Entire CLI', args: ['--version'], parse: (out) => out.trim().split('\n')[0] }

// Each step keeps its own outcome, so one failed call (a branch without a trail, say) hides nothing else.
const STEPS = [
  {
    key: 'status',
    label: 'Repo',
    args: ['status', '--json'],
    parse: JSON.parse,
    summarize: (status) =>
      status.enabled ? `enabled · agents: ${(status.agents ?? []).join(', ') || 'none'}` : 'Entire is not enabled here'
  },
  // A branch without a trail is normal, so this step reports instead of failing the check.
  {
    key: 'trail',
    label: 'Trail',
    args: ['trail', 'show', '--json'],
    optional: true,
    parse: JSON.parse,
    summarize: (trail) => `found (${Object.keys(trail).join(', ')})`
  },
  {
    key: 'checkpoints',
    label: 'Checkpoints',
    args: ['checkpoint', 'list', '--json'],
    parse: JSON.parse,
    summarize: (list) => `${list.length} on this branch`
  }
]

// The panel keeps the newest checkpoints only.
const CHECKPOINT_LIMIT = 20

// Everything the panel and "Entire: Check connection" show for the focused workspace.
export async function collectSnapshot(orca, { signal } = {}) {
  const snapshot = { at: new Date().toISOString(), workspace: null, problem: null, steps: [], data: {} }

  let resolved
  try {
    resolved = await resolveFocusedWorkspace(orca, { signal })
  } catch (error) {
    return { ...snapshot, problem: `Workspace lookup failed: ${error.message}` }
  }
  const { context, path, via, candidates } = resolved
  if (!context) return { ...snapshot, problem: 'No workspace is focused' }
  const workspace = {
    name: context.displayName,
    branch: context.branch,
    terminals: context.terminals.map((terminal) => terminal.id),
    path,
    via
  }
  if (!path) {
    // Without a terminal, only branch and name identify the workspace, and many repos share "main".
    const why = candidates.length > 0 ? `${candidates.length} workspaces match it` : 'no workspace matches it'
    return { ...snapshot, workspace, problem: `${context.displayName} on ${context.branch}: ${why}. Open a terminal in it and try again.` }
  }
  const host = workspaceHost(path)
  workspace.where = host.kind === 'wsl' ? `WSL ${host.distro} ${host.path}` : path

  const version = await runStep(host, VERSION, signal)
  if (!version.ok) return { ...snapshot, workspace, steps: [version.step] }
  const results = await Promise.all(STEPS.map((step) => runStep(host, step, signal)))
  const data = Object.fromEntries(results.filter((result) => result.ok).map((result) => [result.step.key, result.value]))
  if (data.checkpoints) data.checkpoints = data.checkpoints.slice(0, CHECKPOINT_LIMIT)
  return { ...snapshot, workspace, steps: [version.step, ...results.map((result) => result.step)], data }
}

async function runStep(host, { key, label, args, optional = false, parse, summarize = (value) => value }, signal) {
  const step = { key, label, optional, ok: false }
  let result
  try {
    result = await runEntire(host, args, { signal })
  } catch (error) {
    return { ok: false, step: { ...step, text: error.message } }
  }
  if (result.code !== 0) return { ok: false, step: { ...step, text: failureLine(result), ms: result.ms } }
  try {
    const value = parse(result.stdout)
    return { ok: true, value, step: { ...step, ok: true, text: summarize(value), ms: result.ms } }
  } catch {
    return { ok: false, step: { ...step, text: `unexpected output: ${result.stdout.slice(0, 120)}`, ms: result.ms } }
  }
}

// "Entire: Check connection" walks every link the plugin depends on and reports one line per link.
export function connectionReport(orca, snapshot) {
  return [`Orca host API ${orca.api.major}.${orca.api.minor} · Node ${process.version} on ${process.platform}`, ...reportLines(snapshot)].join('\n')
}

export function reportLines({ workspace, problem, steps }) {
  const lines = []
  if (workspace?.where) lines.push(`✓ ${workspace.name} on ${workspace.branch} → ${workspace.where} (via ${workspace.via})`)
  if (problem) lines.push(`✗ ${problem}`)
  for (const step of steps) {
    const mark = step.ok ? '✓' : step.optional ? '·' : '✗'
    lines.push(`${mark} ${step.label}: ${step.text}${step.ms === undefined || !step.ok ? '' : ` (${step.ms} ms)`}`)
  }
  return lines
}

// Orca's notifications take a title of up to 120 characters and a body of up to 1000.
export function connectionNotice(report) {
  const [, ...details] = report.split('\n')
  const ok = !details.some((line) => line.startsWith('✗'))
  return {
    title: ok ? 'Entire: connected' : 'Entire: connection problem',
    body: details.join('\n').slice(0, 1000)
  }
}

// Host API 1.0 gives a panel no channel to its worker, but Orca rereads a development folder's panel
// file when the folder changes and remounts the panel when the HTML differs. So the worker writes
// each snapshot into the panel file, and the panel picks the entry for the focused workspace.
import { readFile, rename, writeFile } from 'node:fs/promises'
import { basename, dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { reportLines } from './doctor.mjs'

export const PLUGIN_ROOT = fileURLToPath(new URL('../../', import.meta.url))
export const TEMPLATE = 'panel/template.html'
// Generated and gitignored; orca-plugin.json names it as the panel's entry.
export const PANEL = 'panel/entire.html'

const DATA = /(<script id="entire-data" type="application\/json">)([\s\S]*?)(<\/script>)/
const MAX_WORKSPACES = 10
// Orca refuses a panel file over 10 MiB; until we have real trail fixtures, cap what one trail adds.
const MAX_TRAIL_CHARS = 100_000

// Orca hashes an installed copy (plugins\<publisher.id>\<content hash>) and refuses it once a byte
// changes, so the worker writes the panel only in a development folder.
export function isInstalledCopy(root) {
  const dir = root.replace(/[\\/]+$/, '')
  return /^[0-9a-f]{32,64}$/i.test(basename(dir)) && basename(dirname(dirname(dir))).toLowerCase() === 'plugins'
}

export function panelEntry(snapshot) {
  const { trail } = snapshot.data
  const data =
    trail && JSON.stringify(trail).length > MAX_TRAIL_CHARS
      ? { ...snapshot.data, trail: { truncated: true, keys: Object.keys(trail) } }
      : snapshot.data
  return { ...snapshot, data, report: reportLines(snapshot) }
}

// Entire's text is untrusted: escaping < > & keeps it from closing the script element it sits in.
export function embedData(data) {
  return JSON.stringify(data).replace(/[<>&  ]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`)
}

export function readData(html) {
  const match = DATA.exec(html)
  try {
    return match ? JSON.parse(match[2]) : null
  } catch {
    return null
  }
}

export function renderPanel(template, data) {
  if (!DATA.test(template)) throw new Error(`${TEMPLATE} has no entire-data script`)
  return template.replace(DATA, (_, open, _old, close) => `${open}${embedData(data)}${close}`)
}

// A newer entry replaces any for the same workspace: same path, or a terminal they share.
export function mergeEntry(data, entry) {
  const same = (other) =>
    (entry.workspace.path && other.workspace.path === entry.workspace.path) ||
    other.workspace.terminals.some((id) => entry.workspace.terminals.includes(id)) ||
    (!other.workspace.path && other.workspace.name === entry.workspace.name && other.workspace.branch === entry.workspace.branch)
  const others = (data?.workspaces ?? []).filter((other) => !same(other))
  return { version: 1, workspaces: [entry, ...others].slice(0, MAX_WORKSPACES) }
}

export async function updatePanel(entry, root = PLUGIN_ROOT) {
  if (isInstalledCopy(root)) return false
  const target = join(root, PANEL)
  const [template, current] = await Promise.all([
    readFile(join(root, TEMPLATE), 'utf8'),
    readFile(target, 'utf8').catch(() => '')
  ])
  await writeAtomically(target, renderPanel(template, mergeEntry(readData(current), entry)))
  return true
}

// Orca refuses a plugin whose panel entry is missing, so a fresh clone needs an empty panel first.
export async function createEmptyPanel(root = PLUGIN_ROOT) {
  const template = await readFile(join(root, TEMPLATE), 'utf8')
  await writeAtomically(join(root, PANEL), renderPanel(template, null))
}

// Orca may read the panel at any moment; a rename never shows it half written.
async function writeAtomically(target, text) {
  await writeFile(`${target}.tmp`, text)
  await rename(`${target}.tmp`, target)
}

