// Rerenders panel/entire.html from the current template with its existing data, then wraps it in a
// stand-in for Orca's panel shell (window.orca and dark tokens) as panel-preview.html.
import { readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const repo = process.argv[2]
const { readData, renderPanel } = await import(pathToFileURL(join(repo, 'src', 'worker', 'panel.mjs')).href)
const panelPath = join(repo, 'panel', 'entire.html')
const data = readData(await readFile(panelPath, 'utf8'))
const html = renderPanel(await readFile(join(repo, 'panel', 'template.html'), 'utf8'), data)
await writeFile(panelPath, html)

const shim = `<!doctype html><html class="dark"><head><meta charset="utf-8">
<style>:root{--orca-background:#18181b;--orca-foreground:#e4e4e7;--orca-muted-foreground:#a1a1aa;--orca-border:#2e2e33;--orca-destructive:#f87171;--orca-radius:6px} body{width:300px;outline:1px dashed #444}</style>
<script>
var params = new URLSearchParams(location.search)
window.orca = { api: { major: 1, minor: 0 }, on: function () { return { dispose: function () {} } },
  host: { has: function () { return true }, call: function () {
    if (params.get('ctx') === 'none') return Promise.resolve(null)
    return Promise.resolve({ displayName: params.get('name') || 'main', branch: params.get('branch') || 'main', terminals: [{ id: params.get('t') || 'term_286e5730-e750-444c-8b4b-5486514bf0a7' }] }) } } }
</script></head>
`
await writeFile(fileURLToPath(new URL('panel-preview.html', import.meta.url)), shim + html)
console.log(`${data?.workspaces.length ?? 0} workspaces, ${html.length} chars`)

