// What the panel shows of `entire trail show --json` (shape in test/fixtures/trail-show.json): the
// trail, the repositories and branches it spans, and the merge gates of the change this branch is.
const BODY_LIMIT = 400

export function trailSummary(trail) {
  const changes = Array.isArray(trail.changes) ? trail.changes : []
  const current = changes.find((change) => change.current) ?? changes.find((change) => change.mergeability) ?? null
  return {
    number: trail.number ?? null,
    title: trail.title ?? '',
    status: trail.status ?? null,
    type: trail.type ?? null,
    priority: trail.priority && trail.priority !== 'none' ? trail.priority : null,
    body: typeof trail.body === 'string' ? trail.body.slice(0, BODY_LIMIT) : '',
    changes: changes.map((change) => ({
      repository: change.repository ?? '',
      branch: change.branch ?? '',
      status: change.status ?? null,
      current: change === current
    })),
    merge: current?.mergeability ? mergeSummary(current.mergeability) : null
  }
}

function mergeSummary(mergeability) {
  return {
    mergeable: Boolean(mergeability.mergeable),
    conflicts: mergeability.conflict_status && mergeability.conflict_status !== 'clean' ? mergeability.conflict_status : null,
    // No fixture has a check run yet, so read the likely fields.
    checks: (mergeability.checks?.runs ?? []).map((run) => ({
      name: run.name ?? run.title ?? 'check',
      status: run.conclusion ?? run.status ?? 'unknown'
    })),
    gates: (mergeability.gates ?? []).map((gate) => ({
      key: gate.gate_key ?? gate.gate_type ?? 'gate',
      blocking: Boolean(gate.blocking),
      status: gate.status ?? 'unknown',
      rationale: gate.rationale ?? '',
      progress: gateProgress(gate)
    }))
  }
}

// A short count where a gate has one, such as approvals 0/1.
function gateProgress({ gate_type: type, value, finding_count: findings }) {
  if (type === 'approvals' && value) return `${value.approved}/${value.required}`
  if (type === 'findings' && typeof findings === 'number') return String(findings)
  if (type === 'up_to_date' && value?.behind_by > 0) return `${value.behind_by} behind`
  return null
}

