# Runs one harness refresh and records every process it starts and every window that becomes visible.
param([string]$Repo, [string[]]$HarnessArgs)

Add-Type @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class Windows {
  delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc cb, IntPtr lParam);
  [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetClassName(IntPtr hWnd, StringBuilder s, int n);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetWindowText(IntPtr hWnd, StringBuilder s, int n);
  public static List<string> Visible() {
    var list = new List<string>();
    EnumWindows((h, l) => {
      if (!IsWindowVisible(h)) return true;
      uint pid; GetWindowThreadProcessId(h, out pid);
      var c = new StringBuilder(256); GetClassName(h, c, 256);
      var t = new StringBuilder(256); GetWindowText(h, t, 256);
      list.Add(h.ToInt64() + "|" + pid + "|" + c + "|" + t);
      return true;
    }, IntPtr.Zero);
    return list;
  }
}
'@

$before = @{}; foreach ($w in [Windows]::Visible()) { $before[$w.Split('|')[0]] = $true }
$known = @{}; foreach ($p in Get-Process) { $known[$p.Id] = $true }
$started = Get-Date
$harness = Start-Process -FilePath node -ArgumentList (@('scripts/orca-harness/launch.mjs') + $HarnessArgs) -WorkingDirectory $Repo -NoNewWindow -PassThru -RedirectStandardOutput "$PSScriptRoot\watch-harness.out"
$procs = @{}; $windows = @{}
$stopAt = $null
while ($true) {
  foreach ($p in Get-Process) {
    if (-not $known[$p.Id]) { $known[$p.Id] = $true; $procs[$p.Id] = [pscustomobject]@{ Id = $p.Id; Name = $p.ProcessName; Seen = ((Get-Date) - $started).TotalSeconds; Parent = $null; Cmd = $null } }
  }
  foreach ($w in [Windows]::Visible()) {
    $f = $w.Split('|'); if (-not $before[$f[0]] -and -not $windows[$f[0]]) { $windows[$f[0]] = [pscustomobject]@{ Seen = ((Get-Date) - $started).TotalSeconds; Pid = $f[1]; Class = $f[2]; Title = $f[3] } }
  }
  if ($harness.HasExited -and -not $stopAt) { $stopAt = (Get-Date).AddSeconds(3) }
  if ($stopAt -and (Get-Date) -gt $stopAt) { break }
  Start-Sleep -Milliseconds 40
}
$cim = @{}; foreach ($c in Get-CimInstance Win32_Process) { $cim[[int]$c.ProcessId] = $c }
"== new processes ($($procs.Count))"
$procs.Values | Sort-Object Seen | ForEach-Object {
  $c = $cim[[int]$_.Id]
  $parent = if ($c) { $pp = $procs[[int]$c.ParentProcessId]; if ($pp) { "$($pp.Name)#$($pp.Id)" } else { "#$($c.ParentProcessId)" } } else { '(gone)' }
  "{0,5:N2}s  {1,-22} parent {2,-24} {3}" -f $_.Seen, "$($_.Name)#$($_.Id)", $parent, $(if ($c) { $c.CommandLine.Substring(0, [Math]::Min(110, $c.CommandLine.Length)) } else { '' })
}
"== newly visible windows ($($windows.Count))"
$windows.Values | Sort-Object Seen | ForEach-Object { "{0,5:N2}s  pid {1,-6} {2,-32} {3}" -f $_.Seen, $_.Pid, $_.Class, $_.Title }
"== harness output"; Get-Content "$PSScriptRoot\watch-harness.out"

# Runs one harness refresh and prints the tree of processes it starts, from WMI creation events.
param([string]$Repo, [string[]]$HarnessArgs)

