// The worker summarizes `entire trail show` (src/worker/trail.mjs).
function trail(entry) {
  var value = entry.data.trail
  if (!value) {
    var s = step(entry, 'trail')
    var missing = !s || /no discoverable|no trail/i.test(s.text)
    return titled(el('div', missing ? 'empty' : 'empty bad', missing ? 'No trail for this branch.' : s.text), s && s.text)
  }
  var changes = value.changes || []
  var facts = [value.type && sentence(value.type), value.priority && sentence(value.priority) + ' priority', plural(changes.length, 'change', 'changes')]
  var body = add(
    el('div'),
    add(
      el('div', 'trail'),
      titled(el('div', 'name clamp', value.title || 'Untitled trail'), value.title),
      el('div', 'meta', facts.filter(Boolean).join(' · ')),
      value.body ? titled(el('div', 'about clamp', value.body), value.body) : null
    )
  )
  var merge = value.merge
  if (merge) {
    if (merge.conflicts) add(body, row(el('span', 'mark bad', '✕'), el('div', 'clip', 'Conflicts'), el('div', 'meta clip', words(merge.conflicts))))
    ;(merge.gates || []).forEach(function (gate) {
      add(body, gateRow(gate))
    })
    ;(merge.checks || []).forEach(function (check) {
      var tone = /^(passed|success)$/.test(check.status) ? 'ok' : /^(failed|failure|error)$/.test(check.status) ? 'bad' : ''
      add(body, row(el('span', 'mark ' + tone, tone === 'ok' ? '✓' : tone === 'bad' ? '✕' : '○'), el('div', 'clip', check.name), el('div', 'meta clip', words(check.status))))
    })
  }
  changes
    .filter(function (change) {
      return !change.current
    })
    .forEach(function (change) {
      add(body, row(el('span', 'mark', '⎇'), el('div', 'clip', change.repository + ' · ' + change.branch), el('div', 'meta clip', words(change.status || ''))))
    })
  return body
}

function gateRow(gate) {
  var tone = gate.status === 'passed' ? 'ok' : gate.status === 'failed' ? (gate.blocking ? 'bad' : 'warn') : ''
  var mark = el('span', 'mark ' + tone, gate.status === 'passed' ? '✓' : gate.status === 'failed' ? '✕' : '○')
  var label = sentence(gate.key)
  var reason = gate.rationale && gate.rationale.toLowerCase() !== label.toLowerCase() ? gate.rationale : null
  return titled(row(mark, el('div', 'clip', label), reason ? el('div', 'meta clip', reason) : null, gate.progress ? el('span', 'end', gate.progress) : null), gate.rationale)
}

// Ready once every gate passes; Blocked while a blocking gate fails.
function trailBadge(value) {
  if (!value) return ''
  var merge = value.merge
  if (value.status !== 'closed' && merge && merge.mergeable) return el('span', 'count ok', 'Ready')
  var blocked =
    value.status !== 'closed' &&
    merge &&
    (merge.gates || []).some(function (gate) {
      return gate.blocking && gate.status === 'failed'
    })
  return blocked ? el('span', 'count bad', 'Blocked') : value.status ? sentence(value.status) : ''
}

