// Collapsed: severity, status, confidence, the defect and where. Open: the agent's full text and
// how the finding was resolved or why it was dismissed.
function findingCard(finding) {
  var severity = finding.severity ? el('span', 'sev ' + (finding.severity === 'high' ? 'bad' : finding.severity === 'medium' ? 'warn' : ''), finding.severity) : null
  var status = finding.status && finding.status !== 'open' ? el('span', 'pill ' + (finding.status === 'resolved' ? 'ok' : ''), sentence(finding.status)) : null
  var stale = finding.stale ? titled(el('span', 'pill', 'Stale'), 'Found on an earlier version of the code') : null
  var confidence = typeof finding.confidence === 'number' ? titled(el('span', 'meta', Math.round(finding.confidence * 100) + '%'), 'Confidence') : null
  var range = finding.line ? ':' + finding.line + (finding.endLine && finding.endLine !== finding.line ? '–' + finding.endLine : '') : ''
  var where = finding.file ? finding.file + range : null
  var summary = add(
    el('summary'),
    add(el('div', 'spread'), add(el('div', 'tags'), severity, status, stale), confidence),
    el('div', 'finding-title clamp', finding.title || 'Finding'),
    where ? titled(el('div', 'meta mono clip', where), where) : null
  )
  var text = finding.body && finding.body !== finding.title ? el('div', 'text', finding.body) : null
  var reason = finding.reason ? add(el('div', 'reason ' + (finding.status === 'resolved' ? 'ok' : '')), el('b', null, sentence(finding.status || 'note') + ': '), document.createTextNode(finding.reason)) : null
  return add(el('details', 'finding card'), summary, text || reason ? add(el('div', 'finding-body'), text, reason) : null)
}

